import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_a_nonconversion():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_and_recent_across_unequal_groups():
    groups = {
        "a": parse_session_log(["a,1,1", "b,4,0"]),
        "b": parse_session_log(["c,3,1"]),
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_window_boundaries():
    assert conversions_in_window([2, 4, 1], 2) == 5
    assert conversions_in_window([2, 4, 1], 0) == 0
    assert conversions_in_window([2, 4, 1], 4) == 7


def test_parse_whitespace_and_flags():
    assert parse_session_log(["", " \t", "  # note", " a , 1 , 0 ", "b,2, "]) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,1"])
def test_parse_error_includes_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log([" # comment", "a,1,0", "", bad_line])


def test_dedupe_keeps_last_record_and_sorts_survivors():
    events = parse_session_log(["b,5,1", "c,0,0", "a,1,0", "b,1,0"])
    assert dedupe_sessions(events) == [events[1], events[2], events[3]]


def test_daily_counts_respect_range_and_fill_gaps():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_group_ranking_and_rate_order():
    groups = {"z": [{"converted": False}], "c": [{"converted": True}], "b": [], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 5) == ["a", "c", "z"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("c", 1.0), ("z", 0.0)]


def test_streak_requires_consecutive_positive_counts():
    assert longest_conversion_streak([1, 0, 2, 1, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0
